import{_ as e,o,c as r,a3 as n}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"生产控制与前沿研究","description":"","frontmatter":{"translationSource":{"title":"生产控制与前沿研究","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/production-control-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/production-control-and-frontier-research"}]]},"headers":[],"relativePath":"zh/production-control-and-frontier-research.md","filePath":"zh/page-0iirIEzxWlkfel2jMLIWJJ.md"}'),i={name:"zh/production-control-and-frontier-research.md"};function s(t,a,d,l,p,c){return o(),r("div",null,[...a[0]||(a[0]=[n('<div class="logistics-content"><h1 id="生产控制与前沿研究" tabindex="-1">生产控制与前沿研究 <a class="header-anchor" href="#生产控制与前沿研究" aria-label="Permalink to &quot;生产控制与前沿研究&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-14. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>0iirIEzxWlkfel2jMLIWJJ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0iirIEzxWlkfel2jMLIWJJ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5515548b0ac8f945.q90-2df7f7103be0fb88.webp" alt="生产控制与前沿研究"></p><p><span id="source-block-DWqjx1xibQYINqsd5UEFOm"></span></p><h2 id="阻塞控制原理-又名-阻塞生产原理、爆仓动力学" tabindex="-1">阻塞控制原理（又名：阻塞生产原理、爆仓动力学） <a class="header-anchor" href="#阻塞控制原理-又名-阻塞生产原理、爆仓动力学" aria-label="Permalink to &quot;阻塞控制原理（又名：阻塞生产原理、爆仓动力学）&quot;">​</a></h2><p>（咕咕咕，大部头施工中……要忙毕业开始缓更）</p><p><a href="https://www.skland.com/article?id=6331180" target="_blank" rel="noreferrer">jnk 的相关介绍文章</a></p><p><a href="/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices">讲解：自配平产线和自适应装置</a></p><p>撰写人：kokobird（1-5节）有问题请找我</p><details><summary>b站</summary><p>蓝海露花_kokobird，但我难得看b站，还不如在群里找我</p></details><p>最后更新：2026年11月3日（\\today）</p><p>状态：目前正在第5节缓慢施工中，第1、2节在准备找时间整理补充。</p><p><span id="source-block-rCxnzFpo8mWaztoa5WoVYx"></span></p><h3 id="_1-引言" tabindex="-1">1 引言 <a class="header-anchor" href="#_1-引言" aria-label="Permalink to &quot;1 引言&quot;">​</a></h3><p><span class="mark-rose_red">欢迎来到智能生产小课堂，管理员。也许你刚刚按配方建设了简单的产线，对进阶内容跃跃欲试；又或许你已经能独立完成全地区基建的规划与布局，正在百无聊赖地四处冲浪。无论如何，希望本文能在闲暇时光带来或理论或实践的启发，领略到终末地工业独特的魅力所在。也许未来，你也能够建造出别具一格的产线，开创基建的新流派。</span></p><p><a href="/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 那我问你，什么是阻塞控制</a> · <a href="/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production">1.2 采用阻塞控制有什么好处</a> · <a href="/endfield-skydoc/zh/1-3-glossary">1.3 术语表（我自己也没法完全定义清楚，不看也罢）</a> · <a href="/endfield-skydoc/zh/1-4-prerequisite-basics">1.4 前置基础知识（待写）</a></p><p><span id="source-block-9lRjFmYbvOxK5tFFbqXsuJ"></span></p><h3 id="_2-阻塞控制的基本概念与简单例子" tabindex="-1">2 阻塞控制的基本概念与简单例子 <a class="header-anchor" href="#_2-阻塞控制的基本概念与简单例子" aria-label="Permalink to &quot;2 阻塞控制的基本概念与简单例子&quot;">​</a></h3><p>本节介绍阻塞控制的一些基本概念和简单例子。掌握理解本节内容，可以设计针对<span class="mark-rose_red"><strong>单种原料的多种成品</strong></span>的阻塞生产方案，达成大部分简单的智能生产需求。<strong>如果你认为已经掌握此部分内容，可以直接看完2.5节，能看懂就可以直接去第3节。</strong></p><p>值得在开篇处点明的是，在讨论阻塞控制时，往往存在<span class="mark-rose_red"><strong>理论规划</strong></span>与<span class="mark-rose_red"><strong>工程实现</strong></span>两个步骤。在<span class="mark-rose_red"><strong>理论规划</strong></span>阶段，我们讨论<u>需要生产什么成品，多少原料，需要什么生产环节，物料的流向与分配如何，优先级如何设计</u>等问题，例如我们分析需求发现需要把120蓝铁中X磨粉Y做蓝药，但这个阶段我们并不特别关心如何造一个X个蓝铁磨粉的产线。</p><p>而<span class="mark-rose_red"><strong>工程实现</strong></span>阶段，我们讨论<u>设备的布局，具体用什么结构实现优先级，如何优化结构</u>等问题。事实上，在<span class="mark-rose_red"><strong>理论规划</strong></span>充分的情况下，绝大部分时候工程实现只需要机械地按照方案进行连线即可，优化布线也不是本文所关注的重点（但是仍然很需要技术含量）。因此，后面大部分内容是侧重于<span class="mark-rose_red"><strong>理论规划</strong></span>的分析讨论，而<span class="mark-rose_red"><strong>工程实现</strong></span>中一些常用的工程结构则会放在附录中。</p><p><a href="/endfield-skydoc/zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road">2.1 Hello World：蓝铁矿的命途分叉</a> · <a href="/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking">2.2 花开两朵：切换型阻塞与平衡型阻塞</a> · <a href="/endfield-skydoc/zh/2-3-the-controlled-controlled-branch-and-the-unfree-free-branch">2.3 受控的受控端 &amp; 不自由的自由端 （考虑弃用）</a></p><p>说明：考虑抛弃受控端和自由端的叫法，换成<strong>阻塞端</strong>和<strong>流通端</strong>。因为只考虑分流时，外部限制控制受控端再控制自由端；但是考虑汇流时，方向是反过来的，所以不如还是叫阻塞端和流通端，再单独区分控制关系好了。后面的叫法暂时还没调整</p><p><a href="/endfield-skydoc/zh/2-3-blocking-and-flowing-branches-you-control-me-i-control-you">2.3 阻塞端与流通端：你控控我，我控控你</a> · <a href="/endfield-skydoc/zh/2-4-faster-than-light-upstream-propagation-of-blocking-signals">2.4 阻塞信号の“超光速”反向传播规律</a> · <a href="/endfield-skydoc/zh/2-5-is-a-stash-not-just-a-special-splitter">2.5 箱子不就是特殊的分流器吗？（核心内容⭐）</a> · <a href="/endfield-skydoc/zh/practical-exercise-a-coupled-xircon-yazhen-syringe-line-using-120">实战演练 120蓝铁的壤晶-蓝药耦合产线解析</a> · <a href="/endfield-skydoc/zh/2-6-empty-storage-full-storage-we-need-more-oversupply">2.6 空仓？满仓？我们需要更多的加压！</a> · <a href="/endfield-skydoc/zh/appendix-common-priority-structures">附录 常见的优先级结构设计</a></p><p><span id="source-block-x00nPzaklxsQ7IkqVngiau"></span></p><h3 id="_3-进阶阻塞控制" tabindex="-1">3 进阶阻塞控制 <a class="header-anchor" href="#_3-进阶阻塞控制" aria-label="Permalink to &quot;3 进阶阻塞控制&quot;">​</a></h3><details><summary>还有进阶？！</summary><p>恭喜你，伟大产线的建设者，当你来到这里时，你已经了解了阻塞生产的基本概念，也就是大概明白了它到底是一个什么玩意儿，以及要如何实现它。现在，更广阔的天地已经为你敞开大门，请稍作休息，然后自由翱翔，并享受无尽的可能性吧。</p></details><p>本节定位为更难的生产需求的阻塞生产方案分析，包括：<strong>多原料多成品的自适应配平生产方案，固气、液气转化机零浪费的阻塞生产方案</strong>等。掌握本节内容，能够了解如何将阻塞生产原理与随版本更新出现的新需求相结合，达成更复杂的生产需求，并深入理解阻塞生产的动力学规律。</p><p><a href="/endfield-skydoc/zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about">3.0 配平，自适应，最大价值产出，叽里咕噜说什么呢</a> · <a href="/endfield-skydoc/zh/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 自动配平思想的萌芽：息壤与源石粉末的爱恨情仇</a> · <a href="/endfield-skydoc/zh/3-2-the-highest-mountain-heavy-xiranite-and-pyrrolite">3.2 最高的山山？！重息壤AND灼铜</a> · <a href="/endfield-skydoc/zh/3-3-you-you-xiranite-freeloading-pig">3.3 你……你这头白吃息壤的猪！</a></p><p><span id="source-block-V0u4t2MI93uTva23MwciTO"></span></p><h4 id="_3-4-中电池满仓切换低电池-赫铜满仓切换灼铜等" tabindex="-1">3.4 中电池满仓切换低电池，赫铜满仓切换灼铜等 <a class="header-anchor" href="#_3-4-中电池满仓切换低电池-赫铜满仓切换灼铜等" aria-label="Permalink to &quot;3.4 中电池满仓切换低电池，赫铜满仓切换灼铜等&quot;">​</a></h4><p>考虑移动到<a href="/endfield-skydoc/zh/automatic-switching-for-reactions-with-multiple-raw-materials">复数原料反应的自动切换</a></p><p><a href="https://www.bilibili.com/video/BV1Ecu66TEiv" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Ecu66TEiv</a></p><p><a href="https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=q3e3T5D5Q6d0K7</a></p><p><span id="source-block-q8wRFhJsdttOEPgUXXKzWs"></span></p><h3 id="_4-阻塞生产动力学分析" tabindex="-1">4 阻塞生产动力学分析 <a class="header-anchor" href="#_4-阻塞生产动力学分析" aria-label="Permalink to &quot;4 阻塞生产动力学分析&quot;">​</a></h3><p>本节定位为阻塞生产的理论数值分析，提供一些应用于生产设计的结论的数学推导与证明。对于阻塞生产产线设计无需掌握此节内容，仅需了解结论即可。</p><p><em>注：4.1-4.5节由原“溢流供料系统的动力学与稳定性v3.pdf”拆解而成，故标注AI内容</em></p><details><summary><u>关于本节及之后的AI内容说明</u></summary><p>由于本人精力或能力所限，部分内容为我和AI充分讨论后，让AI直接撰写而成，这些小节会标注“（AI内容）”，并在每节开头附上我的一些注解。这些小节的内容基本能反映我在这一节想要讨论的问题，我也都看过一遍，觉得基本就是OK没太大问题的。并且除了极其数学的证明（我们搞物理的不关心这个.jpg）或者极其困难的问题外（我也还在学习中），我也可以负责解释答疑。</p><p>事实上，我觉得AI写的比我好得多，逻辑完善交代清楚，标注清晰，还有不少数值例子和配图。</p></details><p><a href="/endfield-skydoc/zh/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 从阻塞流理论基石上建起阻塞生产学的大厦（缓更）</a> · <a href="/endfield-skydoc/zh/4-1-modeling-blocking-based-production-dynamics-discrete-continuous-and">（旧） 4.1 阻塞生产动力分析的建模：从离散模型，连续模型到机器动力系统模型</a> · <a href="/endfield-skydoc/zh/4-1-blocking-production-as-a-dynamical-system">4.1 阻塞生产如何成为一个动力系统（AI内容）</a> · <a href="/endfield-skydoc/zh/4-2-two-inputs-two-products-stable-balancing">4.2 两种原料、两种成品-怎样实现稳定配平（AI内容）</a> · <a href="/endfield-skydoc/zh/4-3-intermediate-products-feedback-and-stability">4.3 中间产物怎样改变反馈与稳定性（AI内容）</a> · <a href="/endfield-skydoc/zh/4-4-multi-input-priority-design-and-stability-limits">4.4 多原料系统-优先级设计与稳定性的边界（AI内容）</a> · <a href="/endfield-skydoc/zh/4-5-empty-storage-startup-and-long-term-operation">4.5 从空仓启动到长期运行-产线最终会怎样（AI内容）</a> · <a href="/endfield-skydoc/zh/4-6-equivalence-between-adaptive-operation-and-solving-linear-systems">4.6 自适应过程与线性方程组求解的等价性</a></p><p><span id="source-block-BGhIinqSTRKJwiW5DcmrR3"></span></p><h3 id="_5-阻塞反馈震荡分析" tabindex="-1">5 阻塞反馈震荡分析 <a class="header-anchor" href="#_5-阻塞反馈震荡分析" aria-label="Permalink to &quot;5 阻塞反馈震荡分析&quot;">​</a></h3><p>本节主要关注定量分析由于阻塞而形成的震荡的性质，包括震荡的来源，幅值与相位计算，在不同模块之间的传递过程。如果在关注平均态流量的基础上，还需要计算周期、缓存等性质，则需要阅读此节。</p><p><a href="/endfield-skydoc/zh/5-0-what-do-we-mean-by-oscillations">5.0 当我们说震荡时，我们到底在讨论什么？</a> · <a href="/endfield-skydoc/zh/where-do-the-oscillations-come-from">5.1 到底哪里来的震荡？</a> · <a href="/endfield-skydoc/zh/oscillation-properties-of-automatic-activation-structures">5.2 自动激活结构的震荡性质分析</a> · <a href="/endfield-skydoc/zh/coarse-grained-modeling-based-on-response-delay">5.3 基于响应延迟的粗粒度建模（AI内容）</a> · <a href="/endfield-skydoc/zh/will-oscillatory-input-be-further-amplified">5.4 震荡输入会进一步放大吗？（AI内容）</a> · <a href="/endfield-skydoc/zh/ko-s-workshop">ko鸟的工作室</a></p><p><span id="source-block-X2BQguP94yFfFweLbHLcF1"></span></p><h2 id="零激活物浪费到更广泛的自适应" tabindex="-1">零激活物浪费到更广泛的自适应 <a class="header-anchor" href="#零激活物浪费到更广泛的自适应" aria-label="Permalink to &quot;零激活物浪费到更广泛的自适应&quot;">​</a></h2><blockquote><p>具体装置讲解已移动到：<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的零浪费装置</a></p></blockquote><p>“<strong>通过阻塞信号切换两种状态</strong>，而阻塞信号又受剩余库存量控制，由此形成反馈，最终的结果为稳定的震荡，生产与停工的时间比例<strong>自适应地调配出了所需的比例</strong>。”——kokobird</p><p><span id="source-block-mMMJhvpB2nsi8tOedocEpS"></span></p><h2 id="大周期反应震荡" tabindex="-1">大周期反应震荡 <a class="header-anchor" href="#大周期反应震荡" aria-label="Permalink to &quot;大周期反应震荡&quot;">​</a></h2><p>该课题基础前提二选一（可实现性：1&gt;2）：</p><p>1、工厂生产端对原料的适应区间覆盖两种状态的震荡。</p><p>2、可增加缓存来让机器在积累阶段消耗缓存，且机器过量输入不浪费。（存在击穿的风险）</p><p>我们存在有三种信号检测手段，分别为针对仓库存储的【满仓信号】、【空仓信号】，以及人为控制的【时钟信号】，由此，我们可两两组合以实现长周期震荡，保证仓库内始终存有原料，用以减少空仓配平课题导致的取货口数目增加，也用于减少直接满仓溢流而受取货波形影响造成的原产地无法存入的损耗。</p><p><span id="source-block-RbO6Tb93wuoHSR4UjEgOUb"></span></p><h3 id="满仓-时钟控制" tabindex="-1">满仓-时钟控制 <a class="header-anchor" href="#满仓-时钟控制" aria-label="Permalink to &quot;满仓-时钟控制&quot;">​</a></h3><p>其设计流程为：检测到仓储无法存入（满仓）→放行反应原料，增加消耗→信号存入时钟延时一段时间后，反应终止，开始积累。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-qGkAB86pF3OMhnOvn3sHBM"></span></p><h3 id="空仓-时钟控制" tabindex="-1">空仓-时钟控制 <a class="header-anchor" href="#空仓-时钟控制" aria-label="Permalink to &quot;空仓-时钟控制&quot;">​</a></h3><p>其设计流程为：检测到取货存在空缺（空仓）→阻塞反应原料，开始积累→信号存入时钟延时一段时间后，反应开启，增加消耗。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-xCX4qF1TzuYffAYgPKb9Pg"></span></p><h3 id="满仓-空仓控制" tabindex="-1">满仓-空仓控制 <a class="header-anchor" href="#满仓-空仓控制" aria-label="Permalink to &quot;满仓-空仓控制&quot;">​</a></h3><p>其设计流程为：检测到仓储无法存入（满仓）→放行反应原料，增加消耗→检测到取货存在空缺（空仓）→阻塞反应原料，开始积累。此为一个工作周期。</p><p>其构图为：</p><p><span id="source-block-Bu1wyct41RhwxXeUeBGarA"></span></p><h3 id="时钟-时钟控制" tabindex="-1">时钟-时钟控制 <a class="header-anchor" href="#时钟-时钟控制" aria-label="Permalink to &quot;时钟-时钟控制&quot;">​</a></h3><p><s>我觉得这玩意很诡异兄弟，为什么不直接限速 30p/q unit/min呢.jpg</s></p><p>按照前文，我们可以在堵塞前后均增设时钟，此时等效调控积累阶段时长 T1 s，过耗阶段时长 T2 s，受控工厂消耗速率为v unit/min，T1与T2可调控时钟结构及内容物来更改，若是相同结构，在考虑传导信号迟延恒为 t s时，可以得到其消耗为 vT2/(T1+T2+t) unit/min，可以一定程度上实现p/q的限制消耗。</p><hr><p>数字电路相关转移到<a href="/endfield-skydoc/zh/digital-circuits">数字电路</a></p></div>',1)])])}const u=e(i,[["render",s]]);export{f as __pageData,u as default};
